using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NurseRenderedSkinCalibration {
 [Serializable]public class Result {public Color referenceMedian,nurseMedian;public Vector3 gain;public int samples;public string method;}
 static Texture2D Read(string p){var t=new Texture2D(2,2,TextureFormat.RGBA32,false,true);t.LoadImage(File.ReadAllBytes(p));return t;}
 static float Median(IEnumerable<float> v){var a=v.OrderBy(x=>x).ToArray();return a[a.Length/2];}
 public static void Analyze(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var moe=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));var nurse=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EntityStudioGenerated/RebirthNurseNative/RebirthNurse_Authoring.prefab"));moe.GetComponent<Animator>().enabled=false;nurse.GetComponent<Animator>().enabled=false;var r=moe.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");var nr=nurse.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");var source=NurseAnatomyRender.WorldSkin(r);var target=NurseAnatomyRender.WorldSkin(nr);source.SetTriangles(new int[0],1);target.SetTriangles(new int[0],1);var collider=new GameObject("Reference surface").AddComponent<MeshCollider>();collider.sharedMesh=target;var p=source.vertices;var uv=source.uv;var tri=source.GetTriangles(0);var albedo=Read(AssetDatabase.GetAssetPath(r.sharedMaterial.GetTexture("_Albedo")));var refRender=Read(NurseVisualOptimization.Out+"/MoeFace_Current.png");var nurseRender=Read(NurseVisualOptimization.Out+"/Final_Face.png");var samples=new List<Color>();var comparison=new List<Color>();
 for(int k=0;k<tri.Length;k+=3){int a=tri[k],b=tri[k+1],c=tri[k+2];for(int j=0;j<4;j++){float u=(j+.5f)/4,w=(1-u)*.5f;var pos=p[a]*u+p[b]*w+p[c]*w;if(pos.x>-.012f||pos.x<-.060f||pos.y<1.665f||pos.y>1.77f)continue;var coord=uv[a]*u+uv[b]*w+uv[c]*w;var skin=albedo.GetPixelBilinear(coord.x,coord.y);if(skin.r<.2f||skin.r>skin.g*1.25f||skin.b>skin.g*1.1f)continue;var mapped=new Vector3(pos.x/.8f,pos.y-.088f,.5f);if(mapped.y>1.610f&&mapped.y<1.643f)continue;RaycastHit hit;if(!collider.Raycast(new Ray(mapped,Vector3.back),out hit,1)||hit.normal.z<.25f)continue;var x=refRender.GetPixelBilinear(.5f-pos.x/.36f,.5f+(pos.y-1.72f)/.36f);var y=nurseRender.GetPixelBilinear(.5f-hit.point.x/.31f,.5f+(hit.point.y-1.64f)/.31f);if(x.grayscale<.08f||y.grayscale<.08f||x.r>x.g*1.4f||y.r>y.g*1.4f)continue;samples.Add(x);comparison.Add(y);}}
 if(samples.Count<30)throw new Exception("Too few matched rendered skin samples "+samples.Count);var result=new Result{samples=samples.Count,referenceMedian=new Color(Median(samples.Select(c=>c.r)),Median(samples.Select(c=>c.g)),Median(samples.Select(c=>c.b)),1),nurseMedian=new Color(Median(comparison.Select(c=>c.r)),Median(comparison.Select(c=>c.g)),Median(comparison.Select(c=>c.b)),1),method="Matched intact-side cheek/forehead rendered samples; identical key/fill/ambient, actual native shaders, mapped surface raycast; native red wound/hair/dark samples and Nurse eye belt excluded. This calibrates visible appearance, not an arbitrary raw pixel average."};result.gain=new Vector3(result.referenceMedian.r/result.nurseMedian.r,result.referenceMedian.g/result.nurseMedian.g,result.referenceMedian.b/result.nurseMedian.b);File.WriteAllText(NurseVisualOptimization.Out+"/rendered-skin-calibration.json",JsonUtility.ToJson(result,true));}
}
